uniform float blink_rate : 0.0 .. 5.0 = 2.0;
uniform float spread : 0.0 .. 1.0 = 0.5;
uniform float brightness : 0.0 .. 2.0 = 1.0;
uniform bool inverse = false;
state float ph;
void update() {
  ph = fract(ph + dt * blink_rate);
}
vec3 shade(Led led) {
  fixed s = fixed(led.s);
  fixed phase = atan2(fixed(led.pos.z), fixed(led.pos.x));
  fixed r = sqrt(fixed(led.pos.x * led.pos.x + fixed(led.pos.z * led.pos.z)));
  fixed h = mix(fixed(0.0), fixed(1.0), fract(phase / (fixed(6.28318))));
  fixed v = mix(fixed(0.0), fixed(1.0), fract(r / fixed(spread)));
  fixed a = sin(fixed(ph)) * fixed(0.5) + fixed(0.5);
  fixed col = hsv2rgb(h, fixed(0.9), v * a);
  if (inverse) {
    col = fixed(1.0) - col;
  }
  return vec3(col * fixed(brightness));
}

